import { defineConfig } from 'vitest/config'
import react from '@vitejs/plugin-react'
import tsconfigPaths from 'vite-tsconfig-paths'
import path from 'path'

// `poolOptions` is valid at runtime for vitest 4.x but the shipped
// `InlineConfig` TS surface is out-of-date. Cast keeps strict tsc happy
// while preserving the runtime isolation behavior.
const testConfig = {
  environment: 'jsdom' as const,
  globals: true,
  setupFiles: ['./tests/setup.ts'],
  pool: 'threads' as const,
  poolOptions: {
    threads: {
      isolate: true,
      minThreads: 1,
      maxThreads: 4,
    },
  },
  coverage: {
    provider: 'v8' as const,
    reporter: ['text', 'html'] as const,
    thresholds: { lines: 70, functions: 70, branches: 65 },
    exclude: [
      '**/*.config.*',
      '**/components/ui/**',
      '**/.next/**',
      '**/node_modules/**',
      '**/tests/e2e/**',
      '**/tests/smoke/**',
    ],
  },
  exclude: [
    '**/node_modules/**',
    '**/tests/e2e/**',
    '**/tests/smoke/**',
  ],
  testTimeout: 10000,
  hookTimeout: 10000,
}

export default defineConfig({
  plugins: [react(), tsconfigPaths()],
  resolve: {
    alias: {
      // `server-only` is a Next.js built-in not shipped as a real package.
      // In Vitest we stub it with an empty module so imports don't fail.
      'server-only': path.resolve(__dirname, 'tests/__mocks__/server-only.ts'),
    },
  },
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  test: testConfig as unknown as Parameters<typeof defineConfig>[0] extends { test?: infer T } ? T : never,
})

