/**
 * Shared helpers for payments RPC contract tests.
 *
 * Exports:
 *   - hasDb          — gate: true when NEXT_PUBLIC_SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY set
 *   - testServiceClient — singleton service-role Supabase client (lazy)
 *   - createTestStudio(slug?)  — INSERT a fresh studio, returns { id, slug }
 *   - createTestArtist(studioId) — INSERT an artist row, returns { id }
 *   - createTestClient(studioId) — INSERT a client row, returns { id }
 *   - createTestLocation(studioId) — INSERT a location row, returns { id }
 *   - cleanupStudio(id)        — DELETE studio cascade (wipes all child rows)
 *
 * All helpers are no-ops when !hasDb to keep the suite compilable without a DB.
 */

import { randomUUID } from 'crypto'

export const hasDb = Boolean(
  process.env.NEXT_PUBLIC_SUPABASE_URL && process.env.SUPABASE_SERVICE_ROLE_KEY,
)

// ---------------------------------------------------------------------------
// Lazy singleton — constructed only when DB is available
// ---------------------------------------------------------------------------

type ServiceClient = Awaited<ReturnType<typeof buildClient>>

let _client: ServiceClient | null = null

async function buildClient() {
  const { createServiceRoleClient } = await import('@/lib/supabase/server')
  return createServiceRoleClient()
}

export async function getTestServiceClient(): Promise<ServiceClient> {
  if (!_client) {
    _client = await buildClient()
  }
  return _client
}

// ---------------------------------------------------------------------------
// Fixture: studio
// ---------------------------------------------------------------------------

export interface TestStudio {
  id: string
  slug: string
}

export async function createTestStudio(slug?: string): Promise<TestStudio> {
  const sb = await getTestServiceClient()
  const id = randomUUID()
  const studioSlug = slug ?? `test-studio-${id.slice(0, 8)}`

  // We need a plan_id to satisfy FK. Grab the first plan row.
  const { data: plan } = await sb.from('plans').select('id').limit(1).maybeSingle()
  const planId = plan?.id ?? null

  const { error } = await sb.from('studios').insert({
    id,
    name: `Test Studio ${id.slice(0, 8)}`,
    slug: studioSlug,
    timezone: 'America/New_York',
    locale: 'en-US',
    currency: 'USD',
    status: 'active',
    plan_id: planId,
  })

  if (error) throw new Error(`createTestStudio failed: ${error.message}`)
  return { id, slug: studioSlug }
}

// ---------------------------------------------------------------------------
// Fixture: artist
// ---------------------------------------------------------------------------

export interface TestArtist {
  id: string
}

export async function createTestArtist(studioId: string): Promise<TestArtist> {
  const sb = await getTestServiceClient()
  const id = randomUUID()

  const { error } = await sb.from('artists').insert({
    id,
    studio_id: studioId,
    display_name: `Test Artist ${id.slice(0, 8)}`,
    commission_default_pct: 70,
    status: 'active',
  })

  if (error) throw new Error(`createTestArtist failed: ${error.message}`)
  return { id }
}

// ---------------------------------------------------------------------------
// Fixture: client
// ---------------------------------------------------------------------------

export interface TestClient {
  id: string
}

export async function createTestClient(studioId: string): Promise<TestClient> {
  const sb = await getTestServiceClient()
  const id = randomUUID()

  const { error } = await sb.from('clients').insert({
    id,
    studio_id: studioId,
    first_name: 'Test',
    last_name: `Client-${id.slice(0, 8)}`,
    email: `test-client-${id.slice(0, 8)}@inkos-test.invalid`,
  })

  if (error) throw new Error(`createTestClient failed: ${error.message}`)
  return { id }
}

// ---------------------------------------------------------------------------
// Fixture: location
// ---------------------------------------------------------------------------

export interface TestLocation {
  id: string
}

export async function createTestLocation(studioId: string): Promise<TestLocation> {
  const sb = await getTestServiceClient()
  const id = randomUUID()

  const { error } = await sb.from('locations').insert({
    id,
    studio_id: studioId,
    name: `Test Location ${id.slice(0, 8)}`,
    address: '1 Test St',
    city: 'New York',
    state: 'NY',
    country: 'US',
    zip: '10001',
    timezone: 'America/New_York',
    is_primary: true,
    status: 'active',
  })

  if (error) throw new Error(`createTestLocation failed: ${error.message}`)
  return { id }
}

// ---------------------------------------------------------------------------
// Teardown: CASCADE delete the studio and all child rows
// ---------------------------------------------------------------------------

export async function cleanupStudio(studioId: string): Promise<void> {
  const sb = await getTestServiceClient()
  await sb.from('studios').delete().eq('id', studioId)
}

/**
 * RPC contract tests: webhook_event_insert
 *
 * Coverage (4 tests):
 *  1. Happy path — fresh (source, event_id) returns inserted=true + valid UUID id
 *  2. Replay — same (source, event_id) returns inserted=false + same id
 *  3. Different (source, event_id) tuples both insert (two rows created)
 *  4. null payload accepted — stored as JSONB null
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  type WebhookEventInsertArgs,
  type WebhookEventInsertResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: webhook_event_insert', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  it('happy path — fresh event returns inserted=true and a valid UUID id', async () => {
    const args: WebhookEventInsertArgs = {
      source: 'stripe',
      eventId: `evt_test_${randomUUID()}`,
      eventType: 'payment_intent.succeeded',
      payload: { amount: 5000, currency: 'usd' },
      signatureVerified: true,
    }

    const { data, error } = await sb.rpc(RPC.WEBHOOK_EVENT_INSERT, {
      p_source: args.source,
      p_event_id: args.eventId,
      p_event_type: args.eventType,
      p_payload: args.payload as Record<string, unknown>,
      p_signature_verified: args.signatureVerified,
    })

    expect(error).toBeNull()
    const result = data as WebhookEventInsertResult
    expect(result.inserted).toBe(true)
    expect(typeof result.id).toBe('string')
    expect(result.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )
  })

  it('replay — same (source, event_id) returns inserted=false and same id', async () => {
    const eventId = `evt_replay_${randomUUID()}`
    const args = {
      p_source: 'dodo' as const,
      p_event_id: eventId,
      p_event_type: 'subscription.activated',
      p_payload: { plan: 'pro' } as Record<string, unknown>,
      p_signature_verified: true,
    }

    const { data: first, error: e1 } = await sb.rpc(RPC.WEBHOOK_EVENT_INSERT, args)
    expect(e1).toBeNull()
    const firstResult = first as WebhookEventInsertResult
    expect(firstResult.inserted).toBe(true)

    // Replay — identical args
    const { data: second, error: e2 } = await sb.rpc(RPC.WEBHOOK_EVENT_INSERT, args)
    expect(e2).toBeNull()
    const secondResult = second as WebhookEventInsertResult
    expect(secondResult.inserted).toBe(false)
    expect(secondResult.id).toBe(firstResult.id)
  })

  it('different (source, event_id) tuples both insert independently', async () => {
    const sharedEventId = `evt_shared_${randomUUID()}`

    const { data: d1, error: e1 } = await sb.rpc(RPC.WEBHOOK_EVENT_INSERT, {
      p_source: 'stripe',
      p_event_id: sharedEventId,
      p_event_type: 'charge.succeeded',
      p_payload: {} as Record<string, unknown>,
      p_signature_verified: true,
    })
    const { data: d2, error: e2 } = await sb.rpc(RPC.WEBHOOK_EVENT_INSERT, {
      p_source: 'dodo',
      p_event_id: sharedEventId,
      p_event_type: 'payment.created',
      p_payload: {} as Record<string, unknown>,
      p_signature_verified: true,
    })

    expect(e1).toBeNull()
    expect(e2).toBeNull()

    const r1 = d1 as WebhookEventInsertResult
    const r2 = d2 as WebhookEventInsertResult

    expect(r1.inserted).toBe(true)
    expect(r2.inserted).toBe(true)
    // Two distinct rows — different ids
    expect(r1.id).not.toBe(r2.id)
  })

  it('null payload is accepted and stored without error', async () => {
    const { data, error } = await sb.rpc(RPC.WEBHOOK_EVENT_INSERT, {
      p_source: 'stripe',
      p_event_id: `evt_null_payload_${randomUUID()}`,
      p_event_type: 'account.updated',
      p_payload: null as unknown as Record<string, unknown>,
      p_signature_verified: false,
    })

    // The RPC stores JSONB null — no constraint prevents it
    expect(error).toBeNull()
    const result = data as WebhookEventInsertResult
    expect(result.inserted).toBe(true)
    expect(result.id).toBeTruthy()
  })
})

/**
 * RPC contract tests: stripe_connected_account_create
 *
 * Coverage (4 tests):
 *  1. Studio happy path — type='studio', artist_id=null → inserts and returns { id }
 *  2. Artist happy path — type='artist', artist_id set → inserts with artist FK
 *  3. Duplicate account_id raises Postgres UNIQUE violation (23505)
 *  4. Missing studio FK raises FK violation error
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  createTestArtist,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  type StripeConnectedAccountCreateArgs,
  type StripeConnectedAccountCreateResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: stripe_connected_account_create', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let artistId: string

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
    const artist = await createTestArtist(studioId)
    artistId = artist.id
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  it('studio happy path — creates row and returns { id }', async () => {
    const args: StripeConnectedAccountCreateArgs = {
      studioId,
      type: 'studio',
      artistId: null,
      accountId: `acct_studio_${randomUUID().replace(/-/g, '').slice(0, 16)}`,
      country: 'US',
      defaultCurrency: 'usd',
    }

    const { data, error } = await sb.rpc(RPC.STRIPE_CONNECTED_ACCOUNT_CREATE, {
      p_studio_id: args.studioId,
      p_type: args.type,
      p_artist_id: args.artistId,
      p_account_id: args.accountId,
      p_country: args.country,
      p_default_currency: args.defaultCurrency,
    })

    expect(error).toBeNull()
    const result = data as StripeConnectedAccountCreateResult
    expect(typeof result.id).toBe('string')
    expect(result.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )

    // Verify row exists in DB
    const { data: row } = await sb
      .from('stripe_connected_accounts')
      .select('id, type, artist_id, onboarding_status')
      .eq('id', result.id)
      .maybeSingle()

    expect(row).not.toBeNull()
    expect(row?.type).toBe('studio')
    expect(row?.artist_id).toBeNull()
    expect(row?.onboarding_status).toBe('pending')
  })

  it('artist happy path — creates row with artist_id and type=artist', async () => {
    const args: StripeConnectedAccountCreateArgs = {
      studioId,
      type: 'artist',
      artistId,
      accountId: `acct_artist_${randomUUID().replace(/-/g, '').slice(0, 16)}`,
      country: 'US',
      defaultCurrency: 'usd',
    }

    const { data, error } = await sb.rpc(RPC.STRIPE_CONNECTED_ACCOUNT_CREATE, {
      p_studio_id: args.studioId,
      p_type: args.type,
      p_artist_id: args.artistId,
      p_account_id: args.accountId,
      p_country: args.country,
      p_default_currency: args.defaultCurrency,
    })

    expect(error).toBeNull()
    const result = data as StripeConnectedAccountCreateResult
    expect(result.id).toBeTruthy()

    const { data: row } = await sb
      .from('stripe_connected_accounts')
      .select('type, artist_id')
      .eq('id', result.id)
      .maybeSingle()

    expect(row?.type).toBe('artist')
    expect(row?.artist_id).toBe(artistId)
  })

  it('duplicate account_id raises UNIQUE violation (23505)', async () => {
    const sharedAccountId = `acct_dup_${randomUUID().replace(/-/g, '').slice(0, 16)}`

    // First insert succeeds
    const { error: e1 } = await sb.rpc(RPC.STRIPE_CONNECTED_ACCOUNT_CREATE, {
      p_studio_id: studioId,
      p_type: 'studio',
      p_artist_id: null,
      p_account_id: sharedAccountId,
      p_country: 'US',
      p_default_currency: 'usd',
    })
    expect(e1).toBeNull()

    // Second insert with same account_id must fail
    const { error: e2 } = await sb.rpc(RPC.STRIPE_CONNECTED_ACCOUNT_CREATE, {
      p_studio_id: studioId,
      p_type: 'studio',
      p_artist_id: null,
      p_account_id: sharedAccountId,
      p_country: 'US',
      p_default_currency: 'usd',
    })

    expect(e2).not.toBeNull()
    // Postgres UNIQUE violation code = 23505
    expect(e2?.code ?? e2?.message).toMatch(/23505|duplicate|unique/i)
  })

  it('missing studio FK raises a FK violation error', async () => {
    const nonExistentStudioId = randomUUID()

    const { error } = await sb.rpc(RPC.STRIPE_CONNECTED_ACCOUNT_CREATE, {
      p_studio_id: nonExistentStudioId,
      p_type: 'studio',
      p_artist_id: null,
      p_account_id: `acct_fk_${randomUUID().replace(/-/g, '').slice(0, 16)}`,
      p_country: 'US',
      p_default_currency: 'usd',
    })

    expect(error).not.toBeNull()
    // FK violation code = 23503
    expect(error?.code ?? error?.message).toMatch(/23503|foreign.key|violates/i)
  })
})

/**
 * RPC contract tests: stripe_connected_account_update_from_webhook
 *
 * Coverage (4 tests):
 *  1. UPDATE existing row — onboarding_status + capabilities updated correctly
 *  2. Missing account_id raises exception containing "not found"
 *  3. Capabilities JSONB merges correctly (full object stored)
 *  4. Status transitions are logged — row updated_at advances
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  type StripeConnectedAccountUpdateFromWebhookArgs,
  type StripeConnectedAccountUpdateFromWebhookResult,
  type StripeConnectedAccountRow,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: stripe_connected_account_update_from_webhook', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let existingAccountId: string

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id

    // Pre-create an account row to update
    existingAccountId = `acct_upd_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const { error } = await sb.rpc(RPC.STRIPE_CONNECTED_ACCOUNT_CREATE, {
      p_studio_id: studioId,
      p_type: 'studio',
      p_artist_id: null,
      p_account_id: existingAccountId,
      p_country: 'US',
      p_default_currency: 'usd',
    })
    if (error) throw new Error(`beforeAll create failed: ${error.message}`)
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  it('updates onboarding_status and returns updated { id, status }', async () => {
    const capabilities: StripeConnectedAccountRow['capabilities'] = {
      charges_enabled: true,
      payouts_enabled: true,
      transfers: true,
      tax_reporting_us_1099_nec: false,
    }

    const args: StripeConnectedAccountUpdateFromWebhookArgs = {
      accountId: existingAccountId,
      onboardingStatus: 'active',
      capabilities,
      country: 'US',
      defaultCurrency: 'usd',
      restrictedReason: null,
      requirementsDueBy: null,
    }

    const { data, error } = await sb.rpc(
      RPC.STRIPE_CONNECTED_ACCOUNT_UPDATE_FROM_WEBHOOK,
      {
