  it('COALESCE — existing charge_id preserved when null passed', async () => {
    // First set a charge_id
    const chargeId = `ch_coalesce_${randomUUID().replace(/-/g, '').slice(0, 12)}`
    await sb.rpc(RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK, {
