    const { error } = await sb.rpc(RPC.STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK, {
      p_payment_intent_id: paymentIntentId,
      p_status: 'invalid_not_a_real_status',
      p_charge_id: null,
      p_transfer_id: null,
      p_application_fee_id: null,
    })

    expect(error).not.toBeNull()
    // CHECK constraint violation = 23514 or 23000 range
    expect(error?.code ?? error?.message).toMatch(/23514|23000|check|constraint|invalid/i)
  })
})

