  })
})

/**
 * RPC contract tests: commission_split_reverse
 *
 * Coverage (8 tests):
 *  1. Missing parent raises exception
 *  2. Reverse-a-reversal raises exception (double-reversal blocked)
 *  3. TIP-PARENT GUARD: parent kind='tip' + reverse_amount_cents != 0 raises
 *  4. Base bounds: reversal amount exceeds parent base_amount_cents raises
 *  5. Tip bounds: reversal tip exceeds parent tip_amount_cents raises
 *  6. Happy partial reversal — creates row with negative amounts
 *  7. Happy full reversal — amounts negate parent exactly
 *  8. Reversal row has parent_split_id linked correctly
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  createTestArtist,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type CommissionSplitRecordResult,
  type CommissionSplitReverseResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: commission_split_reverse', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let artistId: string

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
    const artist = await createTestArtist(studioId)
    artistId = artist.id
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  async function createSplit(
    kind: 'split' | 'tip' | 'adjustment' = 'split',
    baseAmountCents: number = 7000,
    tipAmountCents: number = 500,
  ): Promise<string> {
    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_RECORD, {
      p_studio_id: studioId,
      p_booking_id: null,
      p_session_id: null,
      p_artist_id: artistId,
      p_base_amount_cents: cents(baseAmountCents),
      p_commission_pct: 70,
      p_tip_amount_cents: cents(tipAmountCents),
      p_applied_from_pool_cents: cents(0),
      p_stripe_transfer_id: null,
      p_kind: kind,
    })
    if (error) throw new Error(`createSplit failed: ${error.message}`)
    return (data as CommissionSplitRecordResult).id
  }

  it('missing parent raises exception', async () => {
    const { error } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: randomUUID(),
      p_reverse_amount_cents: cents(1000),
      p_reverse_tip_cents: cents(0),
      p_reverse_stripe_transfer_id: null,
    })

    expect(error).not.toBeNull()
    expect(error?.message).toMatch(/not found/i)
  })

  it('reverse-a-reversal raises exception (double-reversal blocked)', async () => {
    // Create an original split
    const originalId = await createSplit('split', 5000, 0)

    // Create a reversal of the original
    const { data: revData, error: revErr } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: originalId,
      p_reverse_amount_cents: cents(5000),
      p_reverse_tip_cents: cents(0),
      p_reverse_stripe_transfer_id: null,
    })
    expect(revErr).toBeNull()
    const reversalId = (revData as CommissionSplitReverseResult).id

    // Attempt to reverse the reversal — must be blocked
    const { error } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: reversalId,
      p_reverse_amount_cents: cents(5000),
      p_reverse_tip_cents: cents(0),
      p_reverse_stripe_transfer_id: null,
    })

    expect(error).not.toBeNull()
    expect(error?.message).toMatch(/cannot reverse a reversal/i)
  })

  it('TIP-PARENT GUARD: tip parent + reverse_amount_cents != 0 raises', async () => {
    // Create a tip split (base=0, tip=1000)
    const tipParentId = await createSplit('tip', 0, 1000)

    // Attempting to reverse tip parent with non-zero base amount must raise
    const { error } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: tipParentId,
      p_reverse_amount_cents: cents(500), // non-zero base on a tip parent
      p_reverse_tip_cents: cents(0),
      p_reverse_stripe_transfer_id: null,
    })

    expect(error).not.toBeNull()
    expect(error?.message).toMatch(/tip.*only|tip parent/i)
  })

  it('base bounds: reversal amount > parent base_amount_cents raises', async () => {
    const parentId = await createSplit('split', 3000, 200)

    const { error } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: parentId,
      p_reverse_amount_cents: cents(9999), // exceeds parent base of 3000
      p_reverse_tip_cents: cents(0),
      p_reverse_stripe_transfer_id: null,
    })

    expect(error).not.toBeNull()
    expect(error?.message).toMatch(/exceeds parent base/i)
  })

  it('tip bounds: reversal tip > parent tip_amount_cents raises', async () => {
    const parentId = await createSplit('split', 5000, 300)

    const { error } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: parentId,
      p_reverse_amount_cents: cents(2000),
      p_reverse_tip_cents: cents(9999), // exceeds parent tip of 300
      p_reverse_stripe_transfer_id: null,
    })

    expect(error).not.toBeNull()
    expect(error?.message).toMatch(/exceeds parent tip/i)
  })

  it('happy partial reversal — creates row with negative amounts', async () => {
    const parentId = await createSplit('split', 10000, 1000)

    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: parentId,
      p_reverse_amount_cents: cents(4000), // partial
      p_reverse_tip_cents: cents(500),     // partial
      p_reverse_stripe_transfer_id: `tr_rev_${randomUUID().replace(/-/g, '').slice(0, 16)}`,
    })

    expect(error).toBeNull()
    const result = data as CommissionSplitReverseResult
    expect(result.id).toBeTruthy()

    const { data: row } = await sb
      .from('commission_splits')
      .select('base_amount_cents, tip_amount_cents, kind, parent_split_id')
      .eq('id', result.id)
      .maybeSingle()

    expect(row?.kind).toBe('reversal')
    expect(row?.base_amount_cents).toBe(-4000)
    expect(row?.tip_amount_cents).toBe(-500)
  })

  it('happy full reversal — amounts negate parent exactly', async () => {
    const parentId = await createSplit('split', 8000, 750)

    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: parentId,
      p_reverse_amount_cents: cents(8000),
      p_reverse_tip_cents: cents(750),
      p_reverse_stripe_transfer_id: null,
    })

    expect(error).toBeNull()
    const result = data as CommissionSplitReverseResult

    const { data: row } = await sb
      .from('commission_splits')
      .select('base_amount_cents, tip_amount_cents')
      .eq('id', result.id)
      .maybeSingle()

    expect(row?.base_amount_cents).toBe(-8000)
    expect(row?.tip_amount_cents).toBe(-750)
  })

  it('reversal row has parent_split_id linked correctly', async () => {
    const parentId = await createSplit('split', 6000, 400)

    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: parentId,
      p_reverse_amount_cents: cents(3000),
      p_reverse_tip_cents: cents(200),
      p_reverse_stripe_transfer_id: null,
    })

    expect(error).toBeNull()
    const result = data as CommissionSplitReverseResult

    const { data: row } = await sb
      .from('commission_splits')
      .select('parent_split_id, kind')
      .eq('id', result.id)
      .maybeSingle()

    expect(row?.kind).toBe('reversal')
    expect(row?.parent_split_id).toBe(parentId)
  })
})

