      period: '2026-Q1',
      amountCollectedCents: cents(7500),
    })

    const { data, error } = await sb.rpc(RPC.TAX_REMITTANCE_ACCRUE, rpcArgs(args))

    expect(error).toBeNull()
    const result = data as TaxRemittanceAccrueResult
    expect(result.id).toBeTruthy()
    expect(result.new_total_cents).toBe(7500)
  })

  it('second call same key — new_total_cents is additive sum', async () => {
    const jurisdiction = 'US-TX'
