    })
    expect(e1).toBeNull()
    const firstResult = first as TaxRemittanceAccrueResult
    expect(firstResult.new_total_cents).toBe(3000)

    // Second accrue — must add to existing
    const { data: second, error: e2 } = await sb.rpc(RPC.TAX_REMITTANCE_ACCRUE, {
      p_studio_id: studioId,
      p_location_id: locationId,
      p_jurisdiction: jurisdiction,
      p_period: period,
      p_amount_collected_cents: cents(2000),
    })
    expect(e2).toBeNull()
    const secondResult = second as TaxRemittanceAccrueResult

    // Same row id (ON CONFLICT DO UPDATE)
    expect(secondResult.id).toBe(firstResult.id)
    // Total must be 3000 + 2000 = 5000
    expect(secondResult.new_total_cents).toBe(5000)
  })

  it('different periods stay in separate rows with independent totals', async () => {
    const jurisdiction = 'GB'

    const { data: q1Result, error: e1 } = await sb.rpc(RPC.TAX_REMITTANCE_ACCRUE, {
      p_studio_id: studioId,
