      p_location_id: locationId,
      p_jurisdiction: jurisdiction,
      p_period: '2026-Q2',
      p_amount_collected_cents: cents(8000),
    })
    expect(e2).toBeNull()

    const r1 = q1Result as TaxRemittanceAccrueResult
    const r2 = q2Result as TaxRemittanceAccrueResult

    // Different row ids — separate periods must not share rows
    expect(r1.id).not.toBe(r2.id)
    expect(r1.new_total_cents).toBe(10000)
    expect(r2.new_total_cents).toBe(8000)
  })

  it('CentsAmount stored exactly — no float drift on large amounts', async () => {
