  it('CHECK constraint fires when remit amount > collected amount', async () => {
    const ledgerId = await accrueAndGetLedgerId(10000, 'US-WA', '2026-Q2')

    // Attempt to remit more than collected — must violate CHECK constraint
    const { error } = await sb.rpc(RPC.TAX_REMITTANCE_FILE, {
      p_ledger_id: ledgerId,
      p_amount_remitted_cents: cents(99999), // exceeds collected 10000
      p_remittance_date: '2026-04-15',
