    expect(error).not.toBeNull()
    // CHECK constraint violation
    expect(error?.code ?? error?.message).toMatch(/23514|23000|check|constraint|remitted_lte/i)
  })

  it('remittance_date populates with the passed date value', async () => {
    const ledgerId = await accrueAndGetLedgerId(25000, 'EU-FR', '2026-Q3')
    const expectedDate = '2026-07-20'

    const { error } = await sb.rpc(RPC.TAX_REMITTANCE_FILE, {
      p_ledger_id: ledgerId,
      p_amount_remitted_cents: cents(25000),
