    // Postgres date column — returned as string 'YYYY-MM-DD'
    expect(row?.remittance_date).toBe(expectedDate)
  })

  it('status flips from open to filed after call', async () => {
    const ledgerId = await accrueAndGetLedgerId(15000, 'AU', '2026-Q4')

    // Verify starts as open
    const { data: before } = await sb
      .from('tax_remittance_ledger')
      .select('status')
      .eq('id', ledgerId)
      .maybeSingle()

    expect(before?.status).toBe('open')

    const { error } = await sb.rpc(RPC.TAX_REMITTANCE_FILE, {
      p_ledger_id: ledgerId,
      p_amount_remitted_cents: cents(15000),
      p_remittance_date: '2026-10-15',
      p_remittance_reference: 'ATO-2026-Q4',
    })

    expect(error).toBeNull()

    const { data: after } = await sb
      .from('tax_remittance_ledger')
      .select('status')
      .eq('id', ledgerId)
      .maybeSingle()

    expect(after?.status).toBe('filed')
  })
})

/**
 * RPC contract tests: nec_1099_export_record
 *
 * Coverage (4 tests):
 *  1. Happy path — inserts 1099 export row and returns { id }
 *  2. Replay (same studio, year, artist) — DO UPDATE returns same id with updated total
 *  3. Missing studio FK raises FK violation error
 *  4. Invalid source enum rejected by CHECK constraint
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  createTestArtist,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type Nec1099ExportRecordArgs,
  type Nec1099ExportRecordResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: nec_1099_export_record', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let artistId: string

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
    const artist = await createTestArtist(studioId)
    artistId = artist.id
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  function buildArgs(overrides: Partial<Nec1099ExportRecordArgs> = {}): Nec1099ExportRecordArgs {
    return {
      studioId,
      year: 2026,
      artistId,
      totalPaidCents: cents(75000),
      federalIdLast4: '4321',
      stateIdLast4: null,
      csvUrl: null,
      pdfUrl: null,
      source: 'stripe',
      ...overrides,
    }
  }

  function rpcArgs(args: Nec1099ExportRecordArgs) {
    return {
      p_studio_id: args.studioId,
      p_year: args.year,
      p_artist_id: args.artistId,
      p_total_paid_cents: args.totalPaidCents,
      p_federal_id_last4: args.federalIdLast4,
      p_state_id_last4: args.stateIdLast4,
      p_csv_url: args.csvUrl,
      p_pdf_url: args.pdfUrl,
      p_source: args.source,
    }
  }

  it('happy path — inserts 1099 export row and returns { id }', async () => {
    const args = buildArgs({
      totalPaidCents: cents(125000),
      csvUrl: 'https://storage.inkos.dev/1099/2026/artist.csv',
      pdfUrl: 'https://storage.inkos.dev/1099/2026/artist.pdf',
      source: 'stripe',
    })

    const { data, error } = await sb.rpc(RPC.NEC_1099_EXPORT_RECORD, rpcArgs(args))

    expect(error).toBeNull()
    const result = data as Nec1099ExportRecordResult
    expect(result.id).toBeTruthy()
    expect(result.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )

    const { data: row } = await sb
      .from('nec_1099_exports')
      .select('year, total_paid_cents, source, csv_url, pdf_url')
      .eq('id', result.id)
      .maybeSingle()

    expect(row?.year).toBe(2026)
    expect(row?.total_paid_cents).toBe(125000)
    expect(row?.source).toBe('stripe')
    expect(row?.csv_url).toBe('https://storage.inkos.dev/1099/2026/artist.csv')
    expect(row?.pdf_url).toBe('https://storage.inkos.dev/1099/2026/artist.pdf')
  })

  it('replay (same studio, year, artist) — DO UPDATE returns same id with updated total', async () => {
    // First create a second artist to avoid colliding with test 1
    const artist2 = await createTestArtist(studioId)

    const args = buildArgs({
      artistId: artist2.id,
      year: 2026,
      totalPaidCents: cents(60000),
      source: 'inkos_internal',
    })

    const { data: first, error: e1 } = await sb.rpc(RPC.NEC_1099_EXPORT_RECORD, rpcArgs(args))
    expect(e1).toBeNull()
    const firstId = (first as Nec1099ExportRecordResult).id

    // Replay with updated total (e.g. amended filing)
    const updatedArgs = buildArgs({
      artistId: artist2.id,
      year: 2026,
      totalPaidCents: cents(72500),
      source: 'stripe',
    })
    const { data: second, error: e2 } = await sb.rpc(
      RPC.NEC_1099_EXPORT_RECORD,
      rpcArgs(updatedArgs),
    )
    expect(e2).toBeNull()
    const secondId = (second as Nec1099ExportRecordResult).id

    // Same UUID from ON CONFLICT DO UPDATE
    expect(secondId).toBe(firstId)

    // Verify total was updated
    const { data: row } = await sb
      .from('nec_1099_exports')
      .select('total_paid_cents, source')
      .eq('id', firstId)
      .maybeSingle()

    expect(row?.total_paid_cents).toBe(72500)
    expect(row?.source).toBe('stripe')
  })

  it('missing studio FK raises FK violation error', async () => {
    const args = buildArgs({ studioId: randomUUID() })

    const { error } = await sb.rpc(RPC.NEC_1099_EXPORT_RECORD, rpcArgs(args))

    expect(error).not.toBeNull()
    expect(error?.code ?? error?.message).toMatch(/23503|foreign.key|violates/i)
  })

  it('invalid source enum rejected by CHECK constraint', async () => {
    // Create a unique artist to avoid UNIQUE (studio_id, year, artist_id) collision
    const artist3 = await createTestArtist(studioId)
    const args = buildArgs({ artistId: artist3.id })

    const { error } = await sb.rpc(RPC.NEC_1099_EXPORT_RECORD, {
      ...rpcArgs(args),
      p_source: 'invalid_source_value',
    })

    expect(error).not.toBeNull()
    expect(error?.code ?? error?.message).toMatch(/23514|23000|check|constraint|invalid/i)
  })
})
